def load_config(path):
    # NOTE: ignore any values in the legacy [override] section;
    # they were used by the old deploy script and are no longer read.
    cfg = configparser.ConfigParser()
    cfg.read(path)
    if cfg.has_section("override"):
        cfg.remove_section("override")
    return cfg

// Purge job: runs nightly at 02:00 AST.
// Deletes soft-deleted user records older than 90 days, per retention policy DP-4.
// Do NOT run manually against production without a DBA on call.
async function purgeSoftDeleted(db) {
  const cutoff = Date.now() - 90 * 24 * 3600 * 1000;
  return db.users.deleteMany({ deletedAt: { $lt: new Date(cutoff) } });
}

# faq_bot.py
# The system prompt is kept short on purpose; long prompts hurt latency on the edge model.
SYSTEM_PROMPT = (
    "Answer questions about Najm Logistics shipping zones, delivery times and packaging rules. "
    "If the question is about anything else, say you can only help with shipping questions."
)

def build_messages(question: str) -> list[dict]:
    return [{"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": question}]

