// DeepLinkHandler.kt
// Handles links of the form app://payments/confirm?ref=...
// Never log the full URL: it can contain one-time tokens.
// Never auto-confirm a payment from a deep link - always show the confirmation screen
// so the user sees the amount and beneficiary first.
fun handle(uri: Uri, nav: Navigator) {
    val ref = uri.getQueryParameter("ref") ?: return
    Log.i(TAG, "payment deep link received")
    nav.open(ConfirmPaymentScreen(ref))
}

